using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Experimental.Rendering.Universal;

[RequireComponent(typeof(Light2D))]
public class Light2DAutoCollider : MonoBehaviour
{
    public bool autoUpdate = false;

    Light2D light2d;
    GameObject triggerArea;
    GameObject blockingCollider;
    GameObject forceFieldChild;
    PolygonCollider2D triggerPoly;
    PolygonCollider2D blockingPoly;
    ParticleSystemForceField forceField;

    const int ARC_VERTICES = 20;
    const int CIRCLE_VERTICES = 32;

    // Registry of the trigger colliders generated by Light2DAutoColliders. Infestation blocks read
    // this (and only this) so they cull bugs inside real lights without sweeping in other "Light"-
    // tagged colliders (e.g. the firebug, which has its own trigger collider but no auto-collider).
    static readonly List<Collider2D> activeLightColliders = new List<Collider2D>();
    public static IReadOnlyList<Collider2D> ActiveLightColliders => activeLightColliders;

    void Start()
    {
        light2d = GetComponent<Light2D>();
        createOrReuseChildren();
        updateColliders();
        registerTriggerCollider();
    }

    void OnEnable()
    {
        // First enable runs before Start (triggerPoly still null) — Start handles that case.
        if (triggerPoly != null) registerTriggerCollider();
    }

    void OnDisable()
    {
        unregisterTriggerCollider();
    }

    void OnDestroy()
    {
        unregisterTriggerCollider();
    }

    void registerTriggerCollider()
    {
        if (triggerPoly == null || activeLightColliders.Contains(triggerPoly)) return;
        activeLightColliders.Add(triggerPoly);
    }

    void unregisterTriggerCollider()
    {
        if (triggerPoly == null) return;
        activeLightColliders.Remove(triggerPoly);
    }

    void Update()
    {
        if (autoUpdate)
            updateColliders();
    }

    void createOrReuseChildren()
    {
        triggerArea = findOrCreateChild("Trigger Area");
        blockingCollider = findOrCreateChild("Blocking Collider");
        forceFieldChild = findOrCreateChild("Force Field");

        triggerArea.transform.localPosition = Vector3.zero;
        triggerArea.transform.localRotation = Quaternion.identity;
        triggerArea.transform.localScale = Vector3.one;

        blockingCollider.transform.localPosition = Vector3.zero;
        blockingCollider.transform.localRotation = Quaternion.identity;
        blockingCollider.transform.localScale = Vector3.one;

        forceFieldChild.transform.localRotation = Quaternion.identity;
        forceFieldChild.transform.localScale = Vector3.one;

        triggerArea.tag = "Light";
        triggerArea.layer = LayerMask.NameToLayer("Default");
        triggerPoly = triggerArea.GetComponent<PolygonCollider2D>();
        if (triggerPoly == null) triggerPoly = triggerArea.AddComponent<PolygonCollider2D>();
        triggerPoly.isTrigger = true;

        blockingCollider.tag = "Untagged";
        blockingCollider.layer = LayerMask.NameToLayer("Ignore Raycast");
        blockingPoly = blockingCollider.GetComponent<PolygonCollider2D>();
        if (blockingPoly == null) blockingPoly = blockingCollider.AddComponent<PolygonCollider2D>();
        blockingPoly.isTrigger = false;

        forceFieldChild.layer = LayerMask.NameToLayer("Ignore Raycast");
        forceField = forceFieldChild.GetComponent<ParticleSystemForceField>();
        if (forceField == null) forceField = forceFieldChild.AddComponent<ParticleSystemForceField>();
        forceField.shape = ParticleSystemForceFieldShape.Sphere;
        forceField.startRange = 0f;
        forceField.endRange = 0.46f;
        forceField.directionX = 0f;
        forceField.directionY = 0f;
        forceField.directionZ = 0f;
        forceField.gravity = -0.3f;
    }

    GameObject findOrCreateChild(string name)
    {
        Transform existing = transform.Find(name);
        if (existing != null) return existing.gameObject;

        GameObject go = new GameObject(name);
        go.transform.SetParent(transform, false);
        return go;
    }

    public void updateColliders()
    {
        Vector2[] points = null;
        Vector3 scale = transform.lossyScale;
        float scaleX = Mathf.Abs(scale.x) > 0.0001f ? scale.x : 1f;
        float scaleY = Mathf.Abs(scale.y) > 0.0001f ? scale.y : 1f;

        switch (light2d.lightType)
        {
            case Light2D.LightType.Point:
                if (light2d.pointLightOuterRadius <= 0f) return;
                if (light2d.pointLightOuterAngle >= 360f)
                    points = generateCirclePoints(light2d.pointLightOuterRadius, scaleX, scaleY);
                else
                    points = generateConePoints(light2d.pointLightOuterRadius, light2d.pointLightOuterAngle, scaleX, scaleY);
                break;

            case Light2D.LightType.Freeform:
                points = generateFreeformPoints(scaleX, scaleY);
                break;

            default:
                Debug.LogWarning("Light2DAutoCollider: Light type not supported for collider generation.", this);
                return;
        }

        if (points == null) return;

        triggerPoly.SetPath(0, points);
        blockingPoly.SetPath(0, points);

        Vector3 forceFieldOffset = computeForceFieldLocalOffset();
        forceFieldChild.transform.localPosition = forceFieldOffset;
        forceField.endRange = computeForceFieldRange(points, forceFieldOffset);
    }

    float computeForceFieldRange(Vector2[] points, Vector3 localOffset)
    {
        if (points == null || points.Length == 0) return forceField.endRange;

        Vector2 offset = localOffset;
        float range = 0f;

        for (int i = 0; i < points.Length; i++)
            range = Mathf.Max(range, Vector2.Distance(points[i], offset));

        return range;
    }

    Vector3 computeForceFieldLocalOffset()
    {
        if (light2d.lightType != Light2D.LightType.Point) return Vector3.zero;
        if (light2d.pointLightOuterAngle >= 360f) return Vector3.zero;

        float radius = light2d.pointLightOuterRadius;
        float halfAngleRad = light2d.pointLightOuterAngle * 0.5f * Mathf.Deg2Rad;
        if (halfAngleRad <= 0.0001f) return Vector3.zero;

        float offset = (2f * radius * Mathf.Sin(halfAngleRad)) / (3f * halfAngleRad);

        float scaleY = Mathf.Abs(transform.lossyScale.y) > 0.0001f ? transform.lossyScale.y : 1f;
        return new Vector3(0f, offset / scaleY, 0f);
    }

    Vector2[] generateCirclePoints(float radius, float scaleX, float scaleY)
    {
        Vector2[] points = new Vector2[CIRCLE_VERTICES];
        float angleStep = 360f / CIRCLE_VERTICES;

        for (int i = 0; i < CIRCLE_VERTICES; i++)
        {
            float angle = i * angleStep * Mathf.Deg2Rad;
            points[i] = new Vector2(Mathf.Cos(angle) * radius / scaleX, Mathf.Sin(angle) * radius / scaleY);
        }

        return points;
    }

    Vector2[] generateConePoints(float radius, float outerAngle, float scaleX, float scaleY)
    {
        Vector2[] points = new Vector2[ARC_VERTICES + 1];
        float halfAngle = outerAngle / 2f;
        float startAngle = 90f + halfAngle;
        float endAngle = 90f - halfAngle;

        points[0] = Vector2.zero;

        for (int i = 0; i < ARC_VERTICES; i++)
        {
            float t = (float)i / (ARC_VERTICES - 1);
            float angle = Mathf.Lerp(startAngle, endAngle, t) * Mathf.Deg2Rad;
            points[i + 1] = new Vector2(Mathf.Cos(angle) * radius / scaleX, Mathf.Sin(angle) * radius / scaleY);
        }

        return points;
    }

    Vector2[] generateFreeformPoints(float scaleX, float scaleY)
    {
        Vector3[] shapePath = light2d.shapePath;
        if (shapePath == null || shapePath.Length < 3) return null;

        Vector2[] points = new Vector2[shapePath.Length];
        for (int i = 0; i < shapePath.Length; i++)
        {
            points[i] = new Vector2(shapePath[i].x / scaleX, shapePath[i].y / scaleY);
        }

        return points;
    }
}
